import{_ as o}from"./chunks/SIH_diagram.BO1pTOUs.js";import{_ as l,C as n,c as r,o as d,j as a,G as t,al as h,a as i}from"./chunks/framework.CT7RwC5a.js";const v=JSON.parse('{"title":"Simulation-In-Hardware (SIH)","description":"","frontmatter":{},"headers":[],"relativePath":"en/sim_sih/index.md","filePath":"en/sim_sih/index.md"}'),p={name:"en/sim_sih/index.md"};function c(m,e,u,f,g,k){const s=n("Badge");return d(),r("div",null,[e[0]||(e[0]=a("h1",{id:"simulation-in-hardware-sih",tabindex:"-1"},[i("Simulation-In-Hardware (SIH) "),a("a",{class:"header-anchor",href:"#simulation-in-hardware-sih","aria-label":'Permalink to "Simulation-In-Hardware (SIH)"'},"​")],-1)),t(s,{type:"tip",text:"PX4 v1.9 (MC)"}),t(s,{type:"tip",text:"PX4 v1.13 (MC, VTOL, FW)"}),e[1]||(e[1]=h('<div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>This simulator is <a href="./../simulation/community_supported_simulators.html">community supported and maintained</a>. It may or may not work with current versions of PX4 (known to work in PX4 v1.14).</p><p>See <a href="./../dev_setup/dev_env.html">Toolchain Installation</a> for information about the environments and tools supported by the core development team.</p></div><p>Simulation-In-Hardware (SIH) is an alternative to <a href="./../simulation/hitl.html">Hardware In The Loop simulation (HITL)</a> for quadrotors, fixed-wing vehicles (airplane), and VTOL tailsitters.</p><p>SIH can be used by new PX4 users to get familiar with PX4 and the different modes and features, and of course to learn to fly a vehicle using an RC controller in simulation, which is not possible using SITL.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>With SIH the whole simulation is running on embedded hardware: the controller, the state estimator, and the simulator. The Desktop computer is only used to display the virtual vehicle.</p><p><img src="'+o+'" alt="Simulator MAVLink API"></p><h3 id="compatibility" tabindex="-1">Compatibility <a class="header-anchor" href="#compatibility" aria-label="Permalink to &quot;Compatibility&quot;">​</a></h3><ul><li>SIH is compatible with all PX4 supported boards except those based on FMUv2.</li><li>SIH for MC quadrotor is supported from PX4 v1.9.</li><li>SIH for FW (airplane) and VTOL tailsitter are supported from PX4 v1.13.</li><li>SIH as SITL (without hardware) from PX4 v1.14.</li><li>SIH for Standard VTOL from PX4 v1.16.</li><li>SIH for MC Hexacopter X from <code>main</code> (expected to be PX4 v1.17).</li></ul><h3 id="benefits" tabindex="-1">Benefits <a class="header-anchor" href="#benefits" aria-label="Permalink to &quot;Benefits&quot;">​</a></h3><p>SIH provides several benefits over HITL:</p><ul><li>It ensures synchronous timing by avoiding the bidirectional connection to the computer. As a result the user does not need such a powerful desktop computer.</li><li>The whole simulation remains inside the PX4 environment. Developers who are familiar with PX4 can more easily incorporate their own mathematical model into the simulator. They can, for instance, modify the aerodynamic model, or noise level of the sensors, or even add a sensor to be simulated.</li><li>The physical parameters representing the vehicle (such as mass, inertia, and maximum thrust force) can easily be modified from the <a href="./../advanced_config/parameter_reference.html#simulation-in-hardware">SIH parameters</a>.</li></ul><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><p>To run the SIH, you will need a:</p><ul><li><p><a href="./../flight_controller/">Flight controller</a>, such as a Pixhawk-series board.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>From PX4 v1.14 you can run <a href="#sih-as-sitl-no-fc">SIH &quot;as SITL&quot;</a>, in which case a flight controller is not required.</p></div></li><li><p><a href="./../getting_started/px4_basic_concepts.html#manual-control">Manual controller</a>: either a <a href="./../getting_started/rc_transmitter_receiver.html">radio control system</a> or a <a href="./../config/joystick.html">joystick</a>.</p></li><li><p>QGroundControl for flying the vehicle via GCS.</p></li><li><p>Development computer for visualizing the virtual vehicle (optional).</p></li></ul><h2 id="check-if-sih-is-in-firmware" tabindex="-1">Check if SIH is in Firmware <a class="header-anchor" href="#check-if-sih-is-in-firmware" aria-label="Permalink to &quot;Check if SIH is in Firmware&quot;">​</a></h2><p>The modules required for SIH are built into most PX4 firmware by default. These include: <a href="./../modules/modules_driver.html#pwm-out-sim"><code>pwm_out_sim</code></a>, <a href="./../modules/modules_system.html#sensor-baro-sim"><code>sensor_baro_sim</code></a>, <a href="./../modules/modules_system.html#sensor-gps-sim"><code>sensor_gps_sim</code></a> and <a href="./../modules/modules_system.html#sensor-mag-sim"><code>sensor_mag_sim</code></a>.</p><p>To check that these are present on your flight controller:</p><ol><li><p>Start QGroundControl.</p></li><li><p>Open <strong>Analyze Tools &gt; Mavlink Console</strong>.</p></li><li><p>Enter the following commands in the console:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pwm_out_sim</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span></code></pre></div><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sensor_baro_sim</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span></code></pre></div><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sensor_gps_sim</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span></code></pre></div><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sensor_mag_sim</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Note that when using SIH on real hardware you do not need to additionally enable the modules using their corresponding parameters (<a href="./../advanced_config/parameter_reference.html#SENS_EN_GPSSIM">SENS_EN_GPSSIM</a>, <a href="./../advanced_config/parameter_reference.html#SENS_EN_BAROSIM">SENS_EN_BAROSIM</a>, <a href="./../advanced_config/parameter_reference.html#SENS_EN_MAGSIM">SENS_EN_MAGSIM</a>).</p></div></li><li><p>If a valid status is returned you can start using SIH.</p></li></ol><p>If any of the returned values above are <code>nsh: MODULENAME: command not found</code>, then you don&#39;t have the module installed. In this case you will have to add them to your board configuration and then rebuild and install the firmware.</p><h3 id="adding-sih-to-the-firmware" tabindex="-1">Adding SIH to the Firmware <a class="header-anchor" href="#adding-sih-to-the-firmware" aria-label="Permalink to &quot;Adding SIH to the Firmware&quot;">​</a></h3><p>Add the following key to the configuration file for your flight controller to include all the required modules (for an example see <a href="https://github.com/PX4/PX4-Autopilot/blob/main/boards/px4/fmu-v6x/default.px4board" target="_blank" rel="noreferrer">boards/px4/fmu-v6x/default.px4board</a>). Then re-build the firmware and flash it to the board.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CONFIG_MODULES_SIMULATION_SIMULATOR_SIH=y</span></span></code></pre></div><details class="details custom-block"><summary>What does this do?</summary><p>This installs the dependencies in <a href="https://github.com/PX4/PX4-Autopilot/blob/main/src/modules/simulation/simulator_sih/Kconfig" target="_blank" rel="noreferrer">simulator_sih/Kconfig</a>. It is equivalent to:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CONFIG_MODULES_SIMULATION_PWM_OUT_SIM=y</span></span>\n<span class="line"><span>CONFIG_MODULES_SIMULATION_SENSOR_BARO_SIM=y</span></span>\n<span class="line"><span>CONFIG_MODULES_SIMULATION_SENSOR_GPS_SIM=y</span></span>\n<span class="line"><span>CONFIG_MODULES_SIMULATION_SENSOR_MAG_SIM=y</span></span></code></pre></div></details><p>As an alterative to updating configuration files manually, you can use the following command to launch a GUI configuration tool, and interactively enable the required modules at the path: <strong>modules &gt; Simulation &gt; simulator_sih</strong>. For example, to update the fmu-v6x configuration you would use:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_fmu-v6x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> boardconfig</span></span></code></pre></div><p>After uploading, check that the required modules are present.</p><h2 id="starting-sih" tabindex="-1">Starting SIH <a class="header-anchor" href="#starting-sih" aria-label="Permalink to &quot;Starting SIH&quot;">​</a></h2><p>To set up/start SIH:</p><ol><li>Connect the flight controller to the desktop computer with a USB cable.</li><li>Open QGroundControl and wait for the flight controller too boot and connect.</li><li>Open <a href="./../config/airframe.html">Vehicle Setup &gt; Airframe</a> then select the desired frame: <ul><li><a href="./../airframes/airframe_reference.html#copter_simulation_sih_quadcopter_x">SIH Quadcopter X</a></li><li><strong>SIH Hexacopter X</strong> (currently only has an airframe for SITL to safe flash so on flight control hardware it has to be manually configured equivalently).</li><li><a href="./../airframes/airframe_reference.html#plane_simulation_sih_plane_aert">SIH plane AERT</a></li><li><a href="./../airframes/airframe_reference.html#vtol_simulation_sih_tailsitter_duo">SIH Tailsitter Duo</a></li><li><a href="./../airframes/airframe_reference.html#vtol_simulation_sih_standard_vtol_quadplane">SIH Standard VTOL QuadPlane</a></li></ul></li></ol><p>The autopilot will then reboot. The <code>sih</code> module is started on reboot, and the vehicle should be displayed on the ground control station map.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>The airplane needs to takeoff in manual mode at full throttle. Also, if the airplane crashes the state estimator might lose its fix.</p></div><h2 id="display-visualisation-optional" tabindex="-1">Display/Visualisation (optional) <a class="header-anchor" href="#display-visualisation-optional" aria-label="Permalink to &quot;Display/Visualisation (optional)&quot;">​</a></h2><p>The SIH-simulated vehicle can be displayed using <a href="./../sim_jmavsim/">jMAVSim</a> as a visualiser.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>SIH does not <em>need</em> a visualiser — you can connect with QGroundControl and fly the vehicle without one.</p></div><p>To display the simulated vehicle:</p><ol><li><p>Close <em>QGroundControl</em> (if open).</p></li><li><p>Unplug and replug the flight controller (allow a few seconds for it to boot).</p></li><li><p>Start jMAVSim by calling the script <strong>jmavsim_run.sh</strong> from a terminal:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./Tools/simulation/jmavsim/jmavsim_run.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -q</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/ttyACM0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -b</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2000000</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span></span></code></pre></div><p>where the flags are:</p><ul><li><code>-q</code> to allow the communication to <em>QGroundControl</em> (optional).</li><li><code>-d</code> to start the serial device <code>/dev/ttyACM0</code> on Linux. On macOS this would be <code>/dev/tty.usbmodem1</code>.</li><li><code>-b</code> to set the serial baud rate to <code>2000000</code>.</li><li><code>-o</code> to start jMAVSim in <em>display Only</em> mode (i.e. the physical engine is turned off and jMAVSim only displays the trajectory given by the SIH in real-time).</li><li>add a flag <code>-a</code> to display an aircraft or <code>-t</code> to display a tailsitter. If this flag is not present a quadrotor will be displayed by default.</li></ul></li><li><p>After few seconds, <em>QGroundControl</em> can be opened again.</p></li></ol><p>At this point, the system can be armed and flown. The vehicle can be observed moving in jMAVSim, and on the QGC <em>Fly</em> view.</p><h2 id="sih-as-sitl-no-fc" tabindex="-1">SIH as SITL (no FC) <a class="header-anchor" href="#sih-as-sitl-no-fc" aria-label="Permalink to &quot;SIH as SITL (no FC)&quot;">​</a></h2><p>SIH can be run as SITL (Software-In-The-Loop) from v1.14. What this means is that the simulation code is executed on the laptop/computer instead of a flight controller, similar to Gazebo or jMAVSim. In this case you don&#39;t need the flight controller hardware.</p><p>To run SIH as SITL:</p><ol><li>Install the <a href="./../dev_setup/dev_env.html">PX4 Development toolchain</a>.</li><li>Run the appropriate make command for each vehicle type (at the root of the PX4-Autopilot repository): <ul><li><p>Quadcopter</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_sitl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sihsim_quadx</span></span></code></pre></div></li><li><p>Hexacopter</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_sitl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sihsim_hex</span></span></code></pre></div></li><li><p>Fixed-wing (plane)</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_sitl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sihsim_airplane</span></span></code></pre></div></li><li><p>XVert VTOL tailsitter</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_sitl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sihsim_xvert</span></span></code></pre></div></li><li><p>Standard VTOL</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_sitl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sihsim_standard_vtol</span></span></code></pre></div></li></ul></li></ol><h3 id="change-simulation-speed" tabindex="-1">Change Simulation Speed <a class="header-anchor" href="#change-simulation-speed" aria-label="Permalink to &quot;Change Simulation Speed&quot;">​</a></h3><p>SITL allows the simulation to be run faster than real time. To run the airplane simulation 10 times faster than real time, run the command:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PX4_SIM_SPEED_FACTOR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">10</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_sitl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sihsim_airplane</span></span></code></pre></div><p>To display the vehicle in jMAVSim during SITL mode, enter the following command in another terminal:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./Tools/simulation/jmavsim/jmavsim_run.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 19410</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -q</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span></span></code></pre></div><ul><li>add a flag <code>-a</code> to display an aircraft or <code>-t</code> to display a tailsitter. If this flag is not present a quadrotor will be displayed by default.</li></ul><h3 id="set-custom-takeoff-location" tabindex="-1">Set Custom Takeoff Location <a class="header-anchor" href="#set-custom-takeoff-location" aria-label="Permalink to &quot;Set Custom Takeoff Location&quot;">​</a></h3><p>The takeoff location in SIH on SITL can be set using environment variables. This will override the default takeoff location.</p><p>The variables to set are: <code>PX4_HOME_LAT</code>, <code>PX4_HOME_LON</code>, and <code>PX4_HOME_ALT</code>.</p><p>For example:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PX4_HOME_LAT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">28.452386</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PX4_HOME_LON</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-13.867138</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PX4_HOME_ALT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">28.5</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_sitl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sihsim_quadx</span></span></code></pre></div><h2 id="adding-new-airframes" tabindex="-1">Adding New Airframes <a class="header-anchor" href="#adding-new-airframes" aria-label="Permalink to &quot;Adding New Airframes&quot;">​</a></h2><p><a href="./../dev_airframes/adding_a_new_frame.html">Adding a new airframe</a> for use in SIH simulation is much the same as for other use cases. You still need to configure your vehicle type and <a href="./../config/actuators.html">geometry</a> (<code>CA_</code> parameters) and start any other defaults for that specific vehicle.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Not every vehicle can be simulated with SIH — there are currently <a href="./../advanced_config/parameter_reference.html#SIH_VEHICLE_TYPE">four supported vehicle types</a>, each of which has a relatively rigid implementation in <a href="https://github.com/PX4/PX4-Autopilot/blob/main/src/modules/simulation/simulator_sih/sih.cpp" target="_blank" rel="noreferrer"><code>sih.cpp</code></a>.</p></div><p>The specific differences for SIH simulation airframes are listed in the sections below.</p><p>For all variants of SIH:</p><ul><li><p>Set all the <a href="./../advanced_config/parameter_reference.html#simulation-in-hardware">Simulation In Hardware</a> parameters (prefixed with <code>SIH_</code>) in order to configure the physical model of the vehicle.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Make sure that the <code>SIH_*</code> parameters and the <code>CA_*</code> parameters describe the same vehicle. Note that some of these parameters are redundant!</p></div></li><li><p><code>param set-default SYS_HITL 2</code> to enable SIH on the next boot.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This also disables input from real sensors. For SIH on the FC (only), it also enables the simulated GPS, barometer, magnetometer, and airspeed sensor.</p><p>For SIH on SITL you will need to explicitly enable these sensors as shown below.</p></div></li><li><p><code>param set-default EKF2_GPS_DELAY 0</code> to improve state estimator performance (the assumption of instant GPS measurements would normally be unrealistic, but is accurate for SIH).</p></li></ul><p>For SIH on FC:</p><ul><li>Airframe file goes in <code>ROMFS/px4fmu_common/init.d/airframes</code> and follows the naming template <code>${ID}_${model_name}.hil</code>, where <code>ID</code> is the <code>SYS_AUTOSTART_ID</code> used to select the airframe, and <code>model_name</code> is the airframe model name.</li><li>Add the model name in <code>ROMFS/px4fmu_common/init.d/airframes/CMakeLists.txt</code> to generate a corresponding make target.</li><li>Actuators are configured with <code>HIL_ACT_FUNC*</code> parameters (not the usual <code>PWM_MAIN_FUNC*</code> parameters). This is to avoid using the real actuator outputs in SIH. Similarly, the bitfield for inverting individual actuator output ranges is <code>HIL_ACT_REV</code>, rather than <code>PWM_MAIN_REV</code>.</li></ul><p>For SIH as SITL (no FC):</p><ul><li>Airframe file goes in <code>ROMFS/px4fmu_common/init.d-posix/airframes</code> and follows the naming template <code>${ID}_sihsim_${model_name}</code>, where <code>ID</code> is the <code>SYS_AUTOSTART_ID</code> used to select the airframe, and <code>model_name</code> is the airframe model name.</li><li>Add the model name in <code>src/modules/simulation/simulator_sih/CMakeLists.txt</code> to generate a corresponding make target.</li><li>Actuators are configured as usual with <code>PWM_MAIN_FUNC*</code> and <code>PWM_MAIN_REV</code>.</li><li>Additionally, set: <ul><li><code>PX4_SIMULATOR=${PX4_SIMULATOR:=sihsim}</code></li><li><code>PX4_SIM_MODEL=${PX4_SIM_MODEL:=svtol}</code> (replacing <code>svtol</code> with the airframe model name)</li></ul></li><li>Enable the simulated sensors using <a href="./../advanced_config/parameter_reference.html#SENS_EN_GPSSIM">SENS_EN_GPSSIM</a>, <a href="./../advanced_config/parameter_reference.html#SENS_EN_BAROSIM">SENS_EN_BAROSIM</a>, <a href="./../advanced_config/parameter_reference.html#SENS_EN_MAGSIM">SENS_EN_MAGSIM</a>, and <a href="./../advanced_config/parameter_reference.html#SENS_EN_ARSPDSIM">SENS_EN_ARSPDSIM</a> (this is only needed for SIH-as-SITL): <ul><li><code>param set-default SENS_EN_GPSSIM 1</code></li><li><code>param set-default SENS_EN_BAROSIM 1</code></li><li><code>param set-default SENS_EN_MAGSIM 1</code></li><li><code>param set-default SENS_EN_ARSPDSIM 1</code> (if it is a fixed-wing or VTOL airframe with airspeed sensor)</li></ul></li></ul><p>For specific examples see the <code>_sihsim_</code> airframes in <a href="https://github.com/PX4/PX4-Autopilot/blob/main/ROMFS/px4fmu_common/init.d-posix/airframes/" target="_blank" rel="noreferrer">ROMFS/px4fmu_common/init.d-posix/airframes</a> (SIH as SITL) and <a href="https://github.com/PX4/PX4-Autopilot/tree/main/ROMFS/px4fmu_common/init.d/airframes" target="_blank" rel="noreferrer">ROMFS/px4fmu_common/init.d/airframes</a> (SIH on FC).</p><h2 id="dynamic-models" tabindex="-1">Dynamic Models <a class="header-anchor" href="#dynamic-models" aria-label="Permalink to &quot;Dynamic Models&quot;">​</a></h2><p>The dynamic models for the various vehicles are:</p><ul><li>Quadcopter: <a href="https://github.com/PX4/PX4-Autopilot/raw/main/docs/assets/simulation/SIH_dynamic_model.pdf" target="_blank" rel="noreferrer">pdf report</a>.</li><li>Hexacopter: Equivalent to the Quadcopter but with a symmetric hexacopter x actuation setup.</li><li>Fixed-wing: Inspired by the PhD thesis: &quot;Dynamics modeling of agile fixed-wing unmanned aerial vehicles.&quot; Khan, Waqas, supervised by Nahon, Meyer, McGill University, PhD thesis, 2016.</li><li>Tailsitter: Inspired by the master&#39;s thesis: &quot;Modeling and control of a flying wing tailsitter unmanned aerial vehicle.&quot; Chiappinelli, Romain, supervised by Nahon, Meyer, McGill University, Masters thesis, 2018.</li></ul><h2 id="video" tabindex="-1">Video <a class="header-anchor" href="#video" aria-label="Permalink to &quot;Video&quot;">​</a></h2>',67)),e[2]||(e[2]=a("lite-youtube",{videoid:"PzIpSCRD8Jo",title:"SIH FW demo"},null,-1)),e[3]||(e[3]=a("h2",{id:"credits",tabindex:"-1"},[i("Credits "),a("a",{class:"header-anchor",href:"#credits","aria-label":'Permalink to "Credits"'},"​")],-1)),e[4]||(e[4]=a("p",null,"SIH was originally developed by Coriolis g Corporation. The airplane model and tailsitter models were added by Altitude R&D inc. Both are Canadian companies:",-1)),e[5]||(e[5]=a("ul",null,[a("li",null,"Coriolis g developed a new type of Vertical Takeoff and Landing (VTOL) vehicles based on passive coupling systems;"),a("li",null,[a("a",{href:"https://www.altitude-rd.com/",target:"_blank",rel:"noreferrer"},"Altitude R&D"),i(" is specialized in dynamics, control, and real-time simulation (today relocated in Zurich).")])],-1)),e[6]||(e[6]=a("p",null,"The simulator is released for free under BSD license.",-1))])}const y=l(p,[["render",c]]);export{v as __pageData,y as default};
